20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
22	            throws OwnerIdentityConflictException {
23	        String identityKey = OwnerIdentityKey.of(owner);
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
26	                continue;
27	            }
28	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
29	                throw new OwnerIdentityConflictException(
30	                        "An owner with identity " + identityKey + " already exists");
31	            }
32	        }
33	    }
